  const exploited=ids.find(id=>incidentEvidence.knownExploited[id]);
  if(exploited)return {id:exploited,kind:'exploited',date:incidentEvidence.knownExploited[exploited],summary:'公的機関CISAが実際の悪用を確認しています。個別の被害組織や被害内容は、この診断の登録情報では未確認です。',source:'https://www.cisa.gov/known-exploited-vulnerabilities-catalog',publisher:'CISA'};
